svg.script:
(function() {
  var leftPupil  = document.getElementById('left-pupil');
  var rightPupil = document.getElementById('right-pupil');
  var body       = document.getElementById('body');
  var face       = document.getElementById('face');

  var LEFT_BASE  = { x: 298.459, y: 457.498 };
  var RIGHT_BASE = { x: 622.459, y: 452.498 };
  var EYE_MID    = { x: 460.459, y: 454.998 };
  var PUPIL_MAX  = 65;
  var CENTER     = { x: 480, y: 380 };
  var BODY_MAX   = 6;
  var FACE_MAX   = 18;

  // Spring: stiffness controls speed, damping < 1 causes overshoot (cartoon bounce)
  function Spring(stiffness, damping) {
    this.k = stiffness; this.d = damping;
    this.x = 0; this.y = 0;
    this.vx = 0; this.vy = 0;
  }
  Spring.prototype.update = function(tx, ty) {
    this.vx = (this.vx + (tx - this.x) * this.k) * this.d;
    this.vy = (this.vy + (ty - this.y) * this.k) * this.d;
    this.x += this.vx;
    this.y += this.vy;
  };

  // Eyes: very snappy, noticeable overshoot
  var eyeSpring  = new Spring(0.28, 0.58);
  // Face: punchy with a little settle
  var faceSpring = new Spring(0.18, 0.62);
  // Body: slow and soft, barely overshoots
  var bodySpring = new Spring(0.08, 0.72);

  var tEye  = { x: 0, y: 0 };
  var tFace = { x: 0, y: 0 };
  var tBody = { x: 0, y: 0 };

  function fmt(v) { return 'translate(' + v.x.toFixed(2) + ',' + v.y.toFixed(2) + ')'; }

  function clampedDir(cx, cy, max, mx, my) {
    var dx = mx - cx, dy = my - cy;
    var d = Math.sqrt(dx*dx + dy*dy) || 1;
    var r = Math.min(d, max);
    return { x: dx/d * r, y: dy/d * r };
  }

  function tick() {
    eyeSpring.update(tEye.x,   tEye.y);
    faceSpring.update(tFace.x, tFace.y);
    bodySpring.update(tBody.x, tBody.y);

    leftPupil.setAttribute('cx',  (LEFT_BASE.x  + eyeSpring.x).toFixed(2));
    leftPupil.setAttribute('cy',  (LEFT_BASE.y  + eyeSpring.y).toFixed(2));
    rightPupil.setAttribute('cx', (RIGHT_BASE.x + eyeSpring.x).toFixed(2));
    rightPupil.setAttribute('cy', (RIGHT_BASE.y + eyeSpring.y).toFixed(2));

    face.setAttribute('transform', fmt(faceSpring));
    body.setAttribute('transform', fmt(bodySpring));

    requestAnimationFrame(tick);
  }

  document.addEventListener('mousemove', function(e) {
    var svg  = document.documentElement;
    var rect = svg.getBoundingClientRect();
    var mx = (e.clientX - rect.left) / rect.width  * 960;
    var my = (e.clientY - rect.top)  / rect.height * 741;

    tEye  = clampedDir(EYE_MID.x, EYE_MID.y, PUPIL_MAX, mx, my);
    tFace = clampedDir(CENTER.x,  CENTER.y,  FACE_MAX,  mx, my);
    tBody = clampedDir(CENTER.x,  CENTER.y,  BODY_MAX,  mx, my);
  });

  document.addEventListener('mouseleave', function() {
    tEye  = { x: 0, y: 0 };
    tFace = { x: 0, y: 0 };
    tBody = { x: 0, y: 0 };
  });

  tick();
})();
